{
  "description": "The creature is a large quadrupedal mammal with the overall shape, fur, head and paws of a brown bear, shown in right-facing profile standing on a pale ground with small tufts of grass under its feet. Its body is covered in long shaggy fur that is dark brown on the back, legs and top of the head and lighter cream-tan on the muzzle, lower chest and belly. A single large glossy black curved horn projects from the center of its forehead, and multiple glossy dark reddish-brown chitinous plates with segmented lines and highlights are set into the fur on its back, sides, shoulders, hips and outer legs, with a row of six small oval black openings edged in light fur on the lower side beneath the largest side plate.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with broad muzzle, black nose at the tip, small dark brown eyes on the sides, and lighter tan fur on the muzzle and around the mouth, facing to the right at the front of the body"
    ,
      "where": "front of body, attached to neck"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black horn curving upward and forward to a sharp point, with two small tooth-like spines on the inner curve and a rounded base set into the fur on the forehead",
      "where": "center of forehead between and slightly in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in dense brown fur with slightly darker edges",
      "where": "on top of the head behind the horn, one on each side"
    },
    {
      "part": "eyes",
      "looks_like": "small round dark brown eyes with a slight highlight",
      "where": "on the sides of the head above the muzzle"
    },
    {
      "part": "nose",
      "looks_like": "large black rounded nose with visible nostrils",
      "where": "at the tip of the muzzle on the head"
    },
    {
      "part": "mouth",
      "looks_like": "closed mouth with a dark lower lip line and faint whiskers on the muzzle",
      "where": "on the underside of the muzzle"
    },
    {
      "part": "legs",
      "looks_like": "four thick columnar legs covered in long shaggy dark brown fur, muscular and straight",
      "where": "under the body, two front legs under the chest and two hind legs under the hips"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with long curved light-colored claws protruding from the toes, dark fur on top and pads underneath, resting on the ground",
      "where": "at the ends of each leg"
    },
    {
      "part": "plates",
      "looks_like": "multiple glossy dark reddish-brown chitinous plates with black outlines and segmented ridges that reflect light; includes two small oval plates on the upper back, one large rectangular segmented plate on the mid-side, one large curved segmented plate on the hindquarter, two vertical curved plates on the neck/shoulder, and smaller oval plates on the outer side of each leg; plus a row of six small oval black holes with pale rims in the light fur below the large side plate",
      "where": "scattered across the back, left side, shoulder, hip and outer surfaces of all four legs, embedded in the fur"
    },
    {
      "part": "markings",
      "looks_like": "lighter cream to tan fur contrasting with the darker brown, appearing fluffy and longer",
      "where": "on the muzzle, lower chest, belly and inner lower side"
    },
    {
      "part": "tail",
      "looks_like": "no tail is visible in the view",
      "where": "rear of body not visible"
    },
    {
      "part": "wings",
      "looks_like": "none visible",
      "where": "none"
    },
    {
      "part": "mane",
      "looks_like": "none distinct beyond the shaggy neck fur",
      "where": "none"
    }
  ],
